FROM (VALUES
 ('tv-wall-unit', 'TV Stand', 'tv-stand', 'TV stand with display space and hidden storage, made to your size and finish. Call or WhatsApp us for details.', 'Wood'),
 ('dressing-table', 'Dressing Table with Mirror', 'dressing-table-with-mirror', 'Dressing table with a mirror and storage, made to your size and finish. Call or WhatsApp us for details.', 'Wood'),
 ('table', 'Computer Desk', 'computer-desk', 'Computer desk for home and office, made to your size and finish. Call or WhatsApp us for details.', 'Wood'),
 ('table', 'Study Table', 'study-table', 'Study table for students and home use, made to your size and finish. Call or WhatsApp us for details.', 'Wood'),
 ('table', 'Console Table', 'console-table', 'Console table for your entrance or living area, made to your size and finish. Call or WhatsApp us for details.', 'Wood'),
 ('table', 'Tea Table', 'tea-table', 'Tea table for your living room, made to your size and finish. Call or WhatsApp us for details.', 'Wood'),
 ('cot', 'Hydraulic Storage Cot', 'hydraulic-storage-cot', 'Cot with hydraulic lift storage, so you can keep bedding under the bed. Call or WhatsApp us for details.', 'Wood'),
