-- ===== Which products are made in which finish =====
-- Which products are made in which finish. Finish names must match the keys in src/lib/finishes.js.
-- Add a finish to a product by adding its slug to the array. A finish with no product shows only the description on hover.
-- NOTE: these are starting guesses from the product descriptions. Please correct them to match the real stock.
UPDATE products SET finishes = ARRAY['aroma-walnut', 'rolex-ash-light', 'ralph-wood-light', 'light-pine'] WHERE slug = '2-door-wardrobe';
UPDATE products SET finishes = ARRAY['aroma-walnut', 'mahogany'] WHERE slug = '3-door-wardrobe-mirror';
UPDATE products SET finishes = ARRAY['aroma-walnut', 'ralph-wood-light'] WHERE slug = 'walnut-office-desk';
UPDATE products SET finishes = ARRAY['aroma-walnut', 'light-choco'] WHERE slug = 'modern-walnut-cream-tv-unit';
UPDATE products SET finishes = ARRAY['mahogany', 'dark-choco', 'light-pine'] WHERE slug IN ('king-size-wooden-cot', 'queen-size-wooden-cot');
UPDATE products SET finishes = ARRAY['taj-marble', 'mahogany'] WHERE slug IN ('wall-mounted-pooja-mandir', 'pooja-rack-design-2');
-- Light Pine (starting guess: please correct to match the real stock)
UPDATE products SET finishes = ARRAY['light-pine'] WHERE slug IN ('computer-desk', 'tea-table');